def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    # Find separator rows and columns.
    sep_rows = [r for r in range(h) if all(x == 8 for x in grid[r])]
    sep_cols = [c for c in range(w) if all(grid[r][c] == 8 for r in range(h))]
    row_bounds = [-1] + sep_rows + [h]
    col_bounds = [-1] + sep_cols + [w]
    # Use the top-left region as the pattern and copy it to all other regions.
    r0, r1 = row_bounds[0] + 1, row_bounds[1]
    c0, c1 = col_bounds[0] + 1, col_bounds[1]
    pattern = [grid[r][c0:c1] for r in range(r0, r1)]
    for i in range(len(row_bounds) - 1):
        for j in range(len(col_bounds) - 1):
            if i == 0 and j == 0:
                continue
            ra, rb = row_bounds[i] + 1, row_bounds[i + 1]
            ca, cb = col_bounds[j] + 1, col_bounds[j + 1]
            for dr, row in enumerate(pattern):
                for dc, value in enumerate(row):
                    if ra + dr < rb and ca + dc < cb and value != 3:
                        out[ra + dr][ca + dc] = value
    return out
